}

.nav-icon {
    font-size: 1.1rem;
}

/* ── Content Area ── */
.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    position: relative;
    max-width: 820px;
}

.section-title {
    margin-bottom: 1.5rem;
    font-weight: 600;
    color: #212529;
}

.settings-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.25rem;
}

.action-bar {
    display: flex;
    gap: 0.75rem;
    padding-top: 0.5rem;
}

/* ── Profile ── */
.profile-top {
