@page "/settings"
@using sv_d9f7d115357d4e74afb8a257b21521ab.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <nav class="settings-sidebar" aria-label="Settings sections">
        <h4 class="sidebar-title">Settings</h4>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li>
                    <button class="settings-nav-btn @(ActiveSection == section.Key ? "active" : "")"
                            @onclick="() => SetActiveSection(section.Key)">
                        <span class="nav-icon">@section.Value.Icon</span>
                        <span>@section.Value.Label</span>
                    </button>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastMessage is not null)
        {
            <div class="settings-toast @(_toastIsError ? "toast-error" : "toast-success")" role="alert">
                @_toastMessage
            </div>
        }
    </div>
</div>

@* ── Confirmation dialog overlay ── *@
@if (_confirmDialog is not null)
{
    <div class="modal-backdrop show"></div>
    <div class="modal d-block" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">@_confirmDialog.Title</h5>
                    <button type="button" class="btn-close" @onclick="DismissConfirm"></button>
                </div>
                <div class="modal-body"><p>@_confirmDialog.Message</p></div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="DismissConfirm">Cancel</button>
                    <button class="btn btn-danger" @onclick="AcceptConfirm">@_confirmDialog.ConfirmText</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    // ── Section registry ──
    private record SectionMeta(string Label, string Icon);
    private readonly Dictionary<string, SectionMeta> _sections = new()
    {
        ["profile"] = new("Profile", "👤"),
        ["notifications"] = new("Notifications", "🔔"),
        ["security"] = new("Security", "🔒"),
        ["appearance"] = new("Appearance", "🎨"),
    };

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // ── Toast ──
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // ── Profile state ──
    private UserProfile _savedProfile = default!;
    private string _profileName = "";
    private string _profileEmail = "";
    private string _profileBio = "";
    private string _profileAvatarUrl = "";

    // ── Notification state ──
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelEntry> _channels = [];

    private class ChannelEntry { public string Name { get; set; } = ""; public bool Muted { get; set; } }

    // ── Security state ──
    private SecuritySettings _security = default!;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";

    // ── Appearance state ──
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly string[] _themes = ["Light", "Dark", "System"];
    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    // ── Confirm dialog ──
    private ConfirmDialogModel? _confirmDialog;
    private record ConfirmDialogModel(string Title, string Message, string ConfirmText, Func<Task> OnConfirm);

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData("profile");
        _loading = false;
    }

    private async Task SetActiveSection(string section)
    {
        if (section == ActiveSection) return;
        ActiveSection = section;
        _loading = true;
        await LoadSectionData(section);
        _loading = false;
    }

    private async Task LoadSectionData(string section)
    {
        switch (section)
        {
            case "profile":
                _savedProfile = await SettingsService.GetProfileAsync();
                ResetProfile();
                break;
            case "notifications":
                var prefs = await SettingsService.GetNotificationPrefsAsync();
                _emailNotifications = prefs.EmailNotifications;
                _pushNotifications = prefs.PushNotifications;
                _weeklyDigest = prefs.WeeklyDigest;
                _channels = prefs.MutedChannels.Select(c => new ChannelEntry { Name = c, Muted = true }).ToList();
                break;
            case "security":
                _security = await SettingsService.GetSecuritySettingsAsync();
                _twoFactorEnabled = _security.TwoFactorEnabled;
                _passwordPanelOpen = false;
                _currentPassword = _newPassword = _confirmPassword = "";
                break;
            case "appearance":
                var appearance = await SettingsService.GetAppearanceAsync();
                _theme = appearance.Theme;
                _fontSize = appearance.FontSize;
                _language = appearance.Language;
                _compactMode = appearance.CompactMode;
                break;
        }
    }

    private void ResetProfile()
    {
        _profileName = _savedProfile.DisplayName;
        _profileEmail = _savedProfile.Email;
        _profileBio = _savedProfile.Bio;
        _profileAvatarUrl = _savedProfile.AvatarUrl;
    }

    // ── Toast helper ──
    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();
        try
        {
            await Task.Delay(3000, _toastCts.Token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    // ── Confirm dialog helpers ──
    private void DismissConfirm() => _confirmDialog = null;
    private async Task AcceptConfirm()
    {
        if (_confirmDialog is not null)
        {
            await _confirmDialog.OnConfirm();
            _confirmDialog = null;
        }
    }

    // ── Profile actions ──
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges() => ResetProfile();

    // ── Notification actions ──
    private async Task SaveNotifications()
    {
        var mutedChannels = _channels.Where(c => c.Muted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // ── Security actions ──
    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", true);
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = _newPassword = _confirmPassword = "";
        _passwordPanelOpen = false;
        _security = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevokeSession(ActiveSession session)
    {
        _confirmDialog = new(
            "Revoke Session",
            $"Are you sure you want to revoke the session on \"{session.Device}\" in {session.Location}?",
            "Revoke",
            async () =>
            {
                await SettingsService.RevokeSessionAsync(session.Id);
                _security = await SettingsService.GetSecuritySettingsAsync();
                await ShowToast("Session revoked.");
            });
    }

    // ── Appearance actions ──
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    // ── Render fragments ──
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h3 class="section-title">Profile</h3>

        <div class="profile-top">
            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(_profileAvatarUrl))
                {
                    <img src="@_profileAvatarUrl" alt="Avatar preview" class="avatar-img" />
                }
                else
                {
                    <div class="avatar-placeholder">No avatar</div>
                }
                <small class="text-muted mt-1 avatar-url-display" title="@_profileAvatarUrl">@_profileAvatarUrl</small>
            </div>

            <div class="profile-fields">
                <div class="mb-3">
                    <label class="form-label" for="displayName">Display Name</label>
                    <input id="displayName" class="form-control" @bind="_profileName" />
                </div>
                <div class="mb-3">
                    <label class="form-label" for="email">Email</label>
                    <input id="email" type="email" class="form-control" @bind="_profileEmail" />
                </div>
                <div class="mb-3">
                    <label class="form-label" for="bio">Bio</label>
                    <textarea id="bio" class="form-control" rows="4" @bind="_profileBio"></textarea>
                </div>
            </div>
        </div>

        <div class="action-bar">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h3 class="section-title">Notifications</h3>

        <div class="settings-card mb-4">
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <div class="settings-card mb-4">
            <h5>Muted Channels</h5>
            @if (_channels.Count == 0)
            {
                <p class="text-muted">No channels available.</p>
            }
            else
            {
                @foreach (var channel in _channels)
                {
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="@($"ch-{channel.Name}")" @bind="channel.Muted" />
                        <label class="form-check-label" for="@($"ch-{channel.Name}")">@channel.Name</label>
                    </div>
                }
            }
        </div>

        <div class="action-bar">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h3 class="section-title">Security</h3>

        @* ── Change Password Panel ── *@
        <div class="settings-card mb-4">
            <button class="btn btn-outline-primary w-100 text-start d-flex justify-content-between align-items-center"
                    @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>Change Password</span>
                <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
            </button>

            @if (_passwordPanelOpen)
            {
                <div class="mt-3">
                    <div class="mb-3">
                        <label class="form-label" for="currentPwd">Current Password</label>
                        <input id="currentPwd" type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label" for="newPwd">New Password</label>
                        <input id="newPwd" type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label" for="confirmPwd">Confirm Password</label>
                        <input id="confirmPwd" type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    @if (_security.LastPasswordChange.HasValue)
                    {
                        <small class="text-muted ms-3">Last changed: @_security.LastPasswordChange.Value.ToString("MMM dd, yyyy")</small>
                    }
                </div>
            }
        </div>

        @* ── Two-Factor Authentication ── *@
        <div class="settings-card mb-4">
            <div class="d-flex align-items-center justify-content-between">
                <div>
                    <h5 class="mb-1">Two-Factor Authentication</h5>
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor" @bind="_twoFactorEnabled" />
                </div>
            </div>
        </div>

        @* ── Active Sessions ── *@
        <div class="settings-card">
            <h5>Active Sessions</h5>
            <div class="table-responsive">
                <table class="table table-hover mb-0">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _security.Sessions)
                        {
                            var isCurrent = session.Id == _security.Sessions[0].Id;
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isCurrent)
                                    {
                                        <span class="badge bg-info ms-2">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@FormatRelativeTime(session.LastActive)</td>
                                <td>
                                    @if (!isCurrent)
                                    {
                                        <button class="btn btn-sm btn-outline-danger" @onclick="() => RequestRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <h3 class="section-title">Appearance</h3>

        @* ── Theme ── *@
        <div class="settings-card mb-4">
            <h5>Theme</h5>
            <div class="d-flex gap-3">
                @foreach (var t in _themes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{t}")"
                               value="@t" checked="@(_theme == t)"
                               @onchange="() => _theme = t" />
                        <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                    </div>
                }
            </div>
        </div>

        @* ── Font Size ── *@
        <div class="settings-card mb-4">
            <h5>Font Size</h5>
            <div class="d-flex gap-3">
                @foreach (var fs in _fontSizes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{fs}")"
                               value="@fs" checked="@(_fontSize == fs)"
                               @onchange="() => _fontSize = fs" />
                        <label class="form-check-label" for="@($"fs-{fs}")">@fs</label>
                    </div>
                }
            </div>
        </div>

        @* ── Language ── *@
        <div class="settings-card mb-4">
            <h5>Language</h5>
            <select class="form-select" style="max-width: 280px;" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        @* ── Compact Mode ── *@
        <div class="settings-card mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        @* ── Live Preview ── *@
        <div class="settings-card mb-4">
            <h5>Preview</h5>
            <div class="appearance-preview @GetPreviewClasses()">
                <p class="preview-heading">Dashboard Overview</p>
                <p class="preview-text">This is a preview of how your selected appearance settings will look. Adjust the theme, font size, and layout options above.</p>
                <div class="preview-buttons">
                    <span class="preview-btn primary">Primary Action</span>
                    <span class="preview-btn secondary">Secondary</span>
                </div>
            </div>
        </div>

        <div class="action-bar">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_theme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "system" => "preview-system",
            _ => "preview-light"
        });
        classes.Add(_fontSize.ToLowerInvariant() switch
        {
            "small" => "preview-font-sm",
            "large" => "preview-font-lg",
            _ => "preview-font-md"
        });
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private static string FormatRelativeTime(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

